document.addEventListener("DOMContentLoaded",(function(){const openButtons=document.querySelectorAll(".btn-open-modal"),closeButtons=document.querySelectorAll(".btn-close");openButtons.forEach(button=>{button.addEventListener("click",(function(event){event.preventDefault();const targetModalId=this.getAttribute("data-target"),modal=document.getElementById(targetModalId);modal&&modal.classList.add("show")}))}),closeButtons.forEach(button=>{button.addEventListener("click",(function(){const modal=this.closest(".modal");modal&&modal.classList.remove("show")}))}),window.addEventListener("click",(function(event){event.target.classList.contains("modal")&&event.target.classList.remove("show")})),window.addEventListener("keyup",(function(event){if("Escape"===event.key){const openModal=document.querySelector(".modal.show");openModal&&openModal.classList.remove("show")}}))}));